FONT <- "Arial"

theme_ms <- function() {
  theme_classic(base_size = 7, base_family = FONT) +
    theme(axis.line = element_line(linewidth = 0.3), axis.ticks = element_line(linewidth = 0.3),
          axis.text = element_text(size = 6.5, colour = "black"),
          axis.title = element_text(size = 7), plot.title = element_text(size = 7.5, face = "plain"),
          plot.tag = element_text(size = 9, face = "bold"), legend.text = element_text(size = 6.5),
          legend.title = element_text(size = 6.5), legend.key.size = unit(3, "mm"),
          strip.background = element_blank(), strip.text = element_text(size = 6.5),
          plot.margin = margin(4, 6, 4, 4))
}

# rows: one list per row, list(plots = list(...), widths = c(...)); heights are the relative row heights
W_FULL <- 170; W_HALF <- 85; H_MAX <- 225     # Figure widths and maximum height prescribed by the journal (mm)
save_ms <- function(name, rows, heights, w_mm = W_FULL, h_mm) {
  if (!w_mm %in% c(W_FULL, W_HALF) || h_mm > H_MAX) stop(name, ": figure size does not meet the journal requirements (", w_mm, " x ", h_mm, " mm)")
  draw <- function() {
    grid.newpage()
    pushViewport(viewport(layout = grid.layout(length(rows), 1, heights = unit(heights, "null"))))
    for (r in base::seq_along(rows)) {
      R <- rows[[r]]
      pushViewport(viewport(layout.pos.row = r))
      pushViewport(viewport(layout = grid.layout(1, length(R$plots), widths = unit(R$widths, "null"))))
      for (k in base::seq_along(R$plots)) {
        x <- R$plots[[k]]
        if (inherits(x, "ggplot")) {
          print(x, vp = viewport(layout.pos.col = k))
        } else {
          pushViewport(viewport(layout.pos.col = k)); grid.draw(x); popViewport()
        }
      }
      popViewport(2)
    }
  }
  w <- w_mm / 25.4; h <- h_mm / 25.4
  grDevices::cairo_pdf(file.path(OUT_DIR, base::paste0(name, ".pdf")), width = w, height = h, family = FONT)
  draw(); grDevices::dev.off()
  grDevices::tiff(file.path(OUT_DIR, base::paste0(name, ".tiff")), width = w, height = h, units = "in",
                  res = 600, compression = "lzw", type = "cairo", family = FONT)
  draw(); grDevices::dev.off()
  say("  [figure] ", name, "  ", w_mm, " x ", h_mm, " mm, PDF and 600 dpi TIFF")
}
src <- function(name, df) write.csv(df, file.path(OUT_DIR, base::paste0("source_data_", name, ".csv")),
                                    row.names = FALSE)
need <- function(f) { if (!file.exists(f)) stop("Input file not found: ", f); f }
rd <- function(f) read.csv(need(f), stringsAsFactors = FALSE)

# ---------------- reading ----------------
say("=== Reading the analysis output ===")
CON  <- rd(O("46_limits", "all_pairs_with_limits.csv"))       # 45 pairs; the five within-disease pairs are replaced by the ten-thousand-permutation values
PC   <- rd(O("45_stable", "positive_controls_10k.csv"))
PCN  <- rd(O("45_stable", "positive_control_nulls.csv"))
SEX  <- rd(O("51_sex", "sex_concordance_all_pairs.csv"))
COMP <- rd(O("40_composition", "composition_all_pairs.csv"))
LOADCSV <- rd(O("40_composition", "composition_shared_axis_loadings.csv"))
REM  <- rd(O("40_composition", "composition_axis_removal_pairs.csv"))
if (!base::all(c("a", "b", "kind", "r_before", "r_after_insample", "r_after_leaveout") %in% base::names(REM)) ||
    base::nrow(REM) != 45L) stop("The removal table of step 40 does not have the expected 45 rows; please re-run step 40 first")
REG  <- rd(O("47_region", "region_level_within_disease.csv"))
QS   <- rd(O("44_quality", "within_disease_quality_sensitivity.csv"))
BIM  <- rd(O("43_qc", "bimodality_summary.csv"))
SXC  <- rd(O("41_audit", "sex_check.csv"))
KS   <- rd(O("52_gse198904", "sex_concordance_by_K.csv"))
KD   <- rd(O("52_gse198904", "disease_concordance_by_K.csv"))
stopifnot(base::nrow(CON) == 45L, base::nrow(PC) == 5L, base::nrow(SEX) == 45L)
say("  Concordance of the 45 pairs, ten-thousand-permutation within-disease results, sex control, composition, region, quality and QC tables all read")

say("  Reading the ten effect vectors ...")
EW <- list(); DS <- list()
for (g in base::unlist(DIS)) {
  e <- base::readRDS(need(file.path(RES_DIR, base::paste0(g, "_ewas_final.rds"))))
  if (!base::all(c("probe", "effect", "t", "p") %in% base::names(e))) stop(g, ": the effect table lacks columns")
  EW[[g]] <- e[, c("probe", "effect", "t", "p")]
  DS[[g]] <- base::readRDS(need(file.path(RES_DIR, base::paste0(g, "_design.rds"))))
}
pair_eff <- function(a, b) {
  A <- EW[[a]]; B <- EW[[b]]; cm <- base::intersect(A$probe, B$probe)
  data.frame(x = A$effect[base::match(cm, A$probe)], y = B$effect[base::match(cm, B$probe)])
}

# ---------------- self-check (2): within-disease correlation ----------------
say("")
say("=== Self-checks ===")
for (i in base::seq_len(base::nrow(PC))) {
  d <- pair_eff(PC$fixed[i], PC$permuted[i])
  r <- stats::cor(d$x, d$y, method = "spearman")
  ok <- base::abs(r - PC$rho[i]) < 0.002
  say(sprintf("  %-14s recomputed rho %+.4f | step 45 %+.4f  %s", PC$disease[i], r, PC$rho[i], if (ok) "consistent" else "[FAIL]"))
  if (!ok) stop("Recomputed within-disease correlations differ from step 45; no figures produced")
}
# ---------------- self-check (3): inflation factor ----------------
LAM <- base::vapply(names(EW), function(g) stats::median(EW[[g]]$t^2, na.rm = TRUE) / stats::qchisq(0.5, 1), numeric(1))
KK  <- base::vapply(names(DS), function(g) base::sum(base::grepl("^mpc", base::colnames(DS[[g]]$design))), numeric(1))
for (g in names(LAM)) {
  ok <- base::abs(LAM[[g]] - FROZEN_LAMBDA[[g]]) < 0.01
  say(sprintf("  %-10s lambda recomputed from t %.3f | frozen table %.3f  %s", g, LAM[[g]], FROZEN_LAMBDA[[g]],
              if (ok) "consistent" else "[FAIL]"))
  if (!ok) stop("Inflation factors differ from the frozen settings; no figures produced")
}

# ---------------- composition effects (exactly the algorithm of step 40) ----------------
clr <- function(P) {
  if (base::sum(P <= 0, na.rm = TRUE) > 0) {
    for (i in base::seq_len(base::nrow(P))) {
      z <- P[i, ] <= 0
      if (base::any(z)) { P[i, z] <- 0.65 * base::min(P[i, !z], na.rm = TRUE); P[i, ] <- P[i, ] / base::sum(P[i, ]) }
    }
  }
  L <- base::log(P); L - base::rowMeans(L)
}
EFFC <- list()
for (g in base::unlist(DIS)) {
  D <- DS[[g]]
  cov <- rd(file.path(COV_DIR, base::paste0(g, "_covariates.csv")))
  cov <- cov[base::match(D$gsm, cov$gsm), , drop = FALSE]
  ctc <- base::grep("^ct_", base::names(cov), value = TRUE)
  P <- base::as.matrix(cov[, ctc, drop = FALSE]); base::colnames(P) <- base::sub("^ct_", "", ctc)
  Y <- clr(P)
  X <- D$design[, !base::grepl("^ct_", base::colnames(D$design)), drop = FALSE]
  jg <- base::which(base::colnames(X) == "groupcase")
  q0 <- qr(X[, -jg, drop = FALSE]); gv <- base::as.numeric(D$group == "case")
  gr <- qr.resid(q0, gv)
  EFFC[[g]] <- stats::setNames(base::as.numeric(base::crossprod(gr, qr.resid(q0, Y))) / base::sum(gr^2), base::colnames(Y))
}
cells <- base::Reduce(base::intersect, base::lapply(EFFC, names))
EM <- base::do.call(rbind, base::lapply(base::unlist(DIS), function(g) EFFC[[g]][cells]))
base::rownames(EM) <- base::unlist(DIS)
# As in step 40: scale the effect vector of each cohort to unit length, then take the first singular vector without centring
EU <- EM / base::sqrt(base::rowSums(EM^2))
sv <- base::svd(EU); u1 <- sv$v[, 1]; base::names(u1) <- cells
if (u1[["Neu"]] < 0) u1 <- -u1
share <- sv$d[1]^2 / base::sum(sv$d^2)
# ---------------- self-check (1): common direction and correlations before and after removal ----------------
lc <- stats::setNames(LOADCSV$loading, LOADCSV$cell)
if (lc[["Neu"]] < 0) lc <- -lc
dev_l <- base::max(base::abs(u1[names(lc)] - lc))
say(sprintf("  Common direction: share of the total sum of squares %.1f%%; largest difference from the loadings of step 40 %.4f  %s", 100 * share, dev_l,
            if (dev_l < 0.002) "consistent" else "[FAIL]"))
if (dev_l >= 0.002) stop("Common direction differs from step 40; no figures produced")
kc <- base::match(base::paste(COMP$a, COMP$b), base::paste(REM$a, REM$b))
if (base::any(base::is.na(kc))) stop("The removal table of step 40 does not match the 45 pairs")
COMP$r_before <- base::mapply(function(a, b) stats::cor(EM[a, ], EM[b, ]), COMP$a, COMP$b)
dis_of <- COH2DIS[base::rownames(EU)]
COMP$r_after <- base::mapply(function(a, b) {          # Leave-out: the direction is estimated only from the cohorts of the other disorders
  keep <- base::names(dis_of)[!dis_of %in% c(dis_of[[a]], dis_of[[b]])]
  v <- base::svd(EU[keep, , drop = FALSE])$v[, 1]
  stats::cor(EU[a, ] - base::sum(EU[a, ] * v) * v, EU[b, ] - base::sum(EU[b, ] * v) * v)
}, COMP$a, COMP$b)
dev_c <- base::max(base::abs(COMP$r_before - COMP$r_pearson), base::abs(COMP$r_before - REM$r_before[kc]),
                   base::abs(COMP$r_after - REM$r_after_leaveout[kc]))
say(sprintf("  Correlations of the 45 pairs from the recomputed composition effects (before removal, after leave-out removal): largest difference from the values recorded by step 40 %.2e  %s", dev_c,
            if (dev_c < 1e-6) "consistent" else "[FAIL]"))
if (dev_c >= 1e-6) stop("Recomputed composition effects differ from step 40; no figures produced")
say(sprintf("  Median composition correlation (leave-out removal): cross-disease %+.3f -> %+.3f; within-disease %+.3f -> %+.3f",
            stats::median(COMP$r_before[COMP$kind == "cross"]), stats::median(COMP$r_after[COMP$kind == "cross"]),
            stats::median(COMP$r_before[COMP$kind == "within"]), stats::median(COMP$r_after[COMP$kind == "within"])))
say("  All three self-checks passed")

# Uniform disorder abbreviations and disease-pair labels
CON$A <- COH2DIS[CON$fixed]; CON$B <- COH2DIS[CON$permuted]
pkey <- function(a, b) base::ifelse(base::match(a, ORDER) <= base::match(b, ORDER),
                                    base::paste0(a, "-", b), base::paste0(b, "-", a))
CON$pair <- base::ifelse(CON$kind == "within", CON$A, pkey(CON$A, CON$B))
CR <- CON[CON$kind == "cross", ]; WI <- CON[CON$kind == "within", ]

# ================= Fig1 =================
say(""); say("=== Main figures ===")
