            hjust = 0, size = 2.1, family = FONT) +
  scale_fill_manual(values = DCOL, guide = "none") +
  scale_x_continuous(limits = c(0, 2600), breaks = base::seq(0, 2000, 500), expand = c(0, 0)) +   # Leave enough room for the labels on the right
  labs(x = "Samples (cases coloured; controls grey)", y = NULL, tag = "a") + theme_ms()
steps <- data.frame(i = 1:6, t = c("Data acquisition and harmonisation", "Sample-level verification and QC",
  "Covariate estimation", "Cohort-level association models", "Concordance testing", "Calibration and robustness"),
  d = c("GEO matrices; three array generations; unified probe universe", "Sex and age concordance; SNP-probe identity; bimodality index",
        "12 leukocyte types; DNAm age; DNAm smoking score; batch", "limma with methylation PCs; exposure-associated PCs excluded",
        "Spearman correlation of effects; label-permutation null; four-pairing rule",
        "Within-disease controls; detection limits; sex calibration; region level"))
p1b <- ggplot(steps) +
  geom_rect(aes(xmin = 0, xmax = 10, ymin = -i - 0.42, ymax = -i + 0.42), fill = "#EEF3F8", colour = OI[["blue"]], linewidth = 0.3) +
  geom_text(aes(x = 0.3, y = -i + 0.15, label = base::paste0(i, "  ", t)), hjust = 0, size = 2.3, fontface = "bold", family = FONT) +
  geom_text(aes(x = 0.75, y = -i - 0.18, label = d), hjust = 0, size = 1.95, family = FONT, colour = "grey25") +
  coord_cartesian(xlim = c(0, 10), ylim = c(-6.5, -0.5)) + labs(tag = "b") + theme_void(base_family = FONT) +
  theme(plot.tag = element_text(size = 9, face = "bold"), plot.margin = margin(4, 4, 4, 8))
save_ms("Fig1", list(list(plots = list(p1a, p1b), widths = c(1, 1.1))), heights = 1, h_mm = 70)

# ================= Fig2 =================
lim <- function(v) stats::quantile(v, c(0.001, 0.999), na.rm = TRUE)
f2a <- base::do.call(rbind, base::lapply(base::seq_len(base::nrow(PC)), function(i) {
  d <- pair_eff(PC$fixed[i], PC$permuted[i]); d$dis <- LONG2AB[[PC$disease[i]]]
  d$lab <- sprintf("%s\nrho = %+.3f", LONG2AB[[PC$disease[i]]], PC$rho[i]); d
}))
f2a$lab <- factor(f2a$lab, levels = base::unique(f2a$lab[base::order(base::match(f2a$dis, ORDER))]))
L2 <- lim(c(f2a$x, f2a$y))
# The density plot bins and counts by itself, using only sites within the display window. geom_bin_2d is not used: it assigns bins by floating-point boundaries,
# occasional whole rows or columns stay empty and white lines appear in the figure. The quantile trend strip below still uses all sites and is unaffected by the window.
bin2d <- function(d, L, nb) {
  L <- base::as.numeric(L); bw <- (L[2] - L[1]) / nb
  ok <- d$x >= L[1] & d$x <= L[2] & d$y >= L[1] & d$y <= L[2]
  ix <- base::pmin(nb - 1L, base::floor((d$x[ok] - L[1]) / bw))
  iy <- base::pmin(nb - 1L, base::floor((d$y[ok] - L[1]) / bw))
  ct <- base::tabulate(ix * nb + iy + 1L, nb * nb)
  k <- base::which(ct > 0L) - 1L
  data.frame(x = L[1] + (k %/% nb + 0.5) * bw, y = L[1] + (k %% nb + 0.5) * bw, n = ct[k + 1L], bw = bw)
}
f2w <- base::do.call(rbind, base::lapply(base::split(f2a, f2a$lab, drop = TRUE), function(d) {
  b <- bin2d(d, L2, 60L); b$lab <- d$lab[1]; b }))
f2w$lab <- factor(f2w$lab, levels = levels(f2a$lab))
# Each tile gets a thin outline of the same colour: after pixel rounding in the PDF, adjacent tiles leave hairline white seams, which the outline covers
p2a <- ggplot(f2w, aes(x, y, fill = n, colour = n)) + geom_tile(width = f2w$bw[1], height = f2w$bw[1], linewidth = 0.15) +
  scale_fill_gradient(low = "#D9E6F2", high = "#08306B", trans = "log10", name = "CpGs", aesthetics = c("fill", "colour")) +
  geom_hline(yintercept = 0, linewidth = 0.2, colour = "grey50") + geom_vline(xintercept = 0, linewidth = 0.2, colour = "grey50") +
  scale_x_continuous(breaks = c(-0.2, 0, 0.2)) +
  facet_wrap(~lab, nrow = 1) + coord_cartesian(xlim = L2, ylim = L2) +
  labs(x = "Case–control effect, cohort 1 (M-value difference)", y = "Effect, cohort 2", tag = "a") + theme_ms() +
  theme(legend.position = "right")
# Quantile trend strip: sites are divided into 20 equal groups by the rank of the effect in the first cohort, and the mean percentile of each group in the second cohort is plotted.
# If the two cohorts are unrelated the line is flat at 50; the slope approximates the Spearman rho and reveals a tilt that is hard to see in the scatter.
NQ <- 20L
f2d <- base::do.call(rbind, base::lapply(base::split(f2a, f2a$lab, drop = TRUE), function(d) {
  n <- base::nrow(d)
  px <- 100 * (base::rank(d$x) - 0.5) / n; py <- 100 * (base::rank(d$y) - 0.5) / n
  q <- base::pmin(NQ, base::floor(px / (100 / NQ)) + 1L)
  data.frame(lab = d$lab[1], dis = d$dis[1], bin = base::seq_len(NQ),
             x = base::as.numeric(base::tapply(px, q, base::mean)),
             y = base::as.numeric(base::tapply(py, q, base::mean)),
             n = base::as.integer(base::tabulate(q, NQ)))
}))
f2d$lab <- factor(f2d$lab, levels = levels(f2a$lab)); f2d$dis <- factor(f2d$dis, levels = ORDER)
# The trend strip must use all common sites of each pair: the group sizes must sum to the number of probes recorded by step 45
ntr <- base::tapply(f2d$n, f2d$dis, base::sum)
