  stop("The number of sites used by the quantile trend strip of Fig2a differs from the number of common probes of step 45: ",
       base::paste(sprintf("%s %d/%d", names(npc), ntr[names(npc)], npc), collapse = "; "))
for (k in levels(f2d$dis)) {
  s <- f2d[f2d$dis == k, ]
  say(sprintf("  quantile trend %-4s first group %.1f  last group %.1f  slope %+.3f", k, s$y[1], s$y[NQ],
              stats::coef(stats::lm(y ~ x, data = s))[[2]]))
}
