# ================= Fig6: overlap approach (exploratory) =================
say("  Computing the top-500 overlap of the 45 pairs ...")
ov <- base::do.call(rbind, base::lapply(base::seq_len(base::nrow(CON)), function(i) {
  A <- EW[[CON$fixed[i]]]; B <- EW[[CON$permuted[i]]]; cm <- base::intersect(A$probe, B$probe)
  pa <- A$p[base::match(cm, A$probe)]; pb <- B$p[base::match(cm, B$probe)]
  ta <- cm[base::order(pa)][1:TOP_N]; tb <- cm[base::order(pb)][1:TOP_N]
  k <- length(base::intersect(ta, tb)); expd <- TOP_N^2 / length(cm)
  # The significance test usually paired with the overlap approach: hypergeometric distribution, probability of an overlap of at least k
  ph <- stats::phyper(k - 1, TOP_N, length(cm) - TOP_N, TOP_N, lower.tail = FALSE)
  data.frame(id = CON$id[i], kind = CON$kind[i], pair = CON$pair[i], fixed = CON$fixed[i], permuted = CON$permuted[i],
             n_common = length(cm), overlap = k, fold = k / expd, p_hyper = ph, rho = CON$rho[i], p_rho = CON$p_rho[i])
}))
ov$kind <- factor(base::ifelse(ov$kind == "within", "Within-disease", "Cross-disease"), levels = c("Within-disease", "Cross-disease"))
ov$grp <- factor(base::ifelse(ov$kind == "Within-disease", "Within-disease",
                  base::ifelse(ov$pair == "SCZ-IBD", "SCZ \u00d7 IBD", "Other cross-disease")),
                 levels = c("Within-disease", "SCZ \u00d7 IBD", "Other cross-disease"))
rk <- base::rank(-ov$fold)
wi_ov <- ov[ov$kind == "Within-disease", ]; wi_rk <- rk[ov$kind == "Within-disease"]
say("  Five within-disease pairs: overlap, fold enrichment, rank among the 45 pairs (by fold enrichment), calibrated criterion rho")
for (i in base::order(wi_rk))
  say(sprintf("    %-4s overlap %3d  enrichment %6.2f-fold  rank %4.1f  rho %+.4f", wi_ov$pair[i], wi_ov$overlap[i], wi_ov$fold[i], wi_rk[i], wi_ov$rho[i]))
z0 <- base::sum(ov$overlap == 0)
say("  Pairs with an overlap of 0: ", z0, "", if (z0) " (the horizontal axis uses a pseudo-log scale; zeros are still drawn and not dropped)" else "")
top5 <- ov[base::order(-ov$fold), ][1:5, ]
say("  Five pairs with the highest fold enrichment: ", base::paste(sprintf("%s(%s, %.1f-fold)", top5$id, top5$kind, top5$fold), collapse = "; "))
say(sprintf("  Spearman correlation between fold enrichment of the overlap and the calibrated criterion rho: %.3f", stats::cor(ov$fold, ov$rho, method = "spearman")))
hs <- base::do.call(rbind, base::lapply(base::split(ov, ov$pair), function(z)
  data.frame(pair = z$pair[1], kind = base::as.character(z$kind[1]), n = base::nrow(z), n_hyper_sig = base::sum(z$p_hyper < 0.05),
             p_hyper_max = base::max(z$p_hyper), p_hyper_min = base::min(z$p_hyper))))
say("  Number of pairings with hypergeometric P < 0.05 (by disease pair): ",
    base::paste(sprintf("%s %d/%d", hs$pair, hs$n_hyper_sig, hs$n), collapse = "; "))
# Drawing order: the five within-disease pairs are drawn last so that they are not covered by cross-disease points; labels are positioned one by one, avoiding the zero line and neighbouring points
ov <- ov[base::order(ov$kind == "Within-disease"), ]
lab6 <- ov[ov$kind == "Within-disease", ]
# Labels of IBD, SCZ and PD are placed directly above the points; the points around AD and MDD are too dense, so their labels are moved to the empty area below and connected by thin lines
lab6$lx <- lab6$fold; lab6$ly <- lab6$rho + 0.011
lab6$lx[lab6$pair == "AD"] <- 1.9;  lab6$ly[lab6$pair == "AD"] <- -0.040
lab6$lx[lab6$pair == "MDD"] <- 0.5; lab6$ly[lab6$pair == "MDD"] <- -0.036
seg6 <- lab6[lab6$pair %in% c("AD", "MDD"), ]
p6 <- ggplot(ov, aes(fold, rho, colour = grp)) + geom_point(size = 1.6) +
  geom_segment(data = seg6, aes(x = lx, y = ly + 0.004, xend = fold, yend = rho), inherit.aes = FALSE, linewidth = 0.2, colour = "grey30") +
  geom_text(data = lab6, aes(x = lx, y = ly, label = pair), inherit.aes = FALSE, size = 2, family = FONT, colour = "black") +
  scale_colour_manual(values = c(OI[["green"]], OI[["verm"]], OI[["blue"]]), name = NULL) +
  scale_x_continuous(trans = scales::pseudo_log_trans(sigma = 1, base = 10), breaks = c(0, 1, 3, 10, 30, 100, 300)) +
  geom_hline(yintercept = 0, linewidth = 0.3) +
  labs(x = base::paste0("Top-", TOP_N, " CpG overlap, fold over expectation"),
       y = "Calibrated concordance (Spearman rho)") + theme_ms() + theme(legend.position = "top")
src("Fig6", ov)
save_ms("Fig6", list(list(plots = list(p6), widths = 1)), heights = 1, w_mm = W_HALF, h_mm = 75)

