  scale_fill_manual(values = c("grey70", OI[["green"]]), name = NULL) + geom_hline(yintercept = 0, linewidth = 0.3) +
  labs(x = NULL, y = "Within-disease rho", tag = "b") + theme_ms() + theme(legend.position = "top")
src("FigS3", fs3a); src("FigS3_quality", QS)
save_ms("FigS3", list(list(plots = list(ps3a, ps3b), widths = c(1, 1))), heights = 1, h_mm = 65)

SXC <- SXC[base::is.finite(SXC$concordance), , drop = FALSE]
SXC$gse <- factor(SXC$gse, levels = base::rev(SXC$gse))
fs4a <- rbind(data.frame(gse = SXC$gse, what = "Observed", v = SXC$concordance),
              data.frame(gse = SXC$gse, what = "Labels shuffled", v = SXC$concordance_shuffled))
ps4a <- ggplot(fs4a, aes(v, gse, colour = what)) + geom_point(size = 1.8) +
  scale_colour_manual(values = c(Observed = OI[["blue"]], `Labels shuffled` = "grey60"), name = NULL) +
  labs(x = "Inferred vs recorded sex agreement", y = NULL, tag = "a") + theme_ms() + theme(legend.position = "top")
BIM$gse <- factor(BIM$gse, levels = base::rev(base::unlist(DIS)))
ps4b <- ggplot(BIM, aes(pct_flag, gse)) + geom_col(fill = "grey60", width = 0.65) +
  labs(x = "Samples flagged (%)", y = NULL, tag = "b") + theme_ms()
ps4c <- ggplot(BIM, aes(-base::log10(fisher_p), gse, fill = fisher_p < 0.05)) + geom_col(width = 0.65) +
  scale_fill_manual(values = c(`TRUE` = OI[["verm"]], `FALSE` = "grey70"), guide = "none") +
  geom_vline(xintercept = -base::log10(0.05), linetype = 3) +
  labs(x = "-log10 P, flagged vs case status", y = NULL, tag = "c") + theme_ms()
src("FigS4", BIM); src("FigS4_sex", SXC)
save_ms("FigS4", list(list(plots = list(ps4a, ps4b, ps4c), widths = c(1, 1, 1))), heights = 1, h_mm = 65)

CR$gen <- factor(GENCAT[CR$pair], levels = c("Substantial", "Limited", "None"))
if (base::any(base::is.na(CR$gen))) stop("Disease pairs not assigned to a genetic correlation category: ", base::paste(base::unique(CR$pair[base::is.na(CR$gen)]), collapse = ", "))
ps5 <- ggplot(CR, aes(pair, rho)) +
  annotate("rect", xmin = -Inf, xmax = Inf, ymin = stats::quantile(SEX$rho, 0.25), ymax = stats::quantile(SEX$rho, 0.75), fill = "#FBE9CF") +
  geom_hline(yintercept = stats::median(SEX$rho), colour = OI[["orange"]]) +
  geom_hline(yintercept = WI$rho[WI$pair == "IBD"], colour = OI[["green"]], linetype = 2) +
  geom_point(colour = OI[["blue"]], size = 1.4) + facet_grid(~gen, scales = "free_x", space = "free_x") +
  geom_hline(yintercept = 0, linewidth = 0.3) +
  labs(x = NULL, y = "Cross-disease Spearman rho") + theme_ms() +
  theme(axis.text.x = element_text(angle = 40, hjust = 1))
src("FigS5", CR[, c("pair", "gen", "fixed", "permuted", "rho")])
save_ms("FigS5", list(list(plots = list(ps5), widths = 1)), heights = 1, h_mm = 70)

COMP$A <- COH2DIS[COMP$a]; COMP$B <- COH2DIS[COMP$b]
COMP$pair <- base::ifelse(COMP$kind == "within", COMP$A, pkey(COMP$A, COMP$B))
Mc <- base::matrix(NA_real_, 5, 5, dimnames = list(ORDER, ORDER)); Nc <- Mc
for (a in ORDER) Mc[a, a] <- COMP$r_pearson[COMP$kind == "within" & COMP$pair == a]
for (k in base::unique(COMP$pair[COMP$kind == "cross"])) {
  s <- COMP[COMP$kind == "cross" & COMP$pair == k, ]; ab <- base::strsplit(k, "-")[[1]]
  Mc[ab[1], ab[2]] <- Mc[ab[2], ab[1]] <- stats::median(s$r_pearson)
  Nc[ab[1], ab[2]] <- Nc[ab[2], ab[1]] <- base::sum(s$p_pearson < 0.05)
}
fs6 <- base::expand.grid(r = ORDER, c = ORDER, stringsAsFactors = FALSE)
fs6$v <- Mc[base::cbind(fs6$r, fs6$c)]; fs6$n <- Nc[base::cbind(fs6$r, fs6$c)]
fs6$txt <- base::ifelse(fs6$r == fs6$c, sprintf("%+.2f", fs6$v), sprintf("%+.2f\n%d/4", fs6$v, fs6$n))
fs6$r <- factor(fs6$r, levels = base::rev(ORDER)); fs6$c <- factor(fs6$c, levels = ORDER)
ps6 <- ggplot(fs6, aes(c, r, fill = v)) + geom_tile(colour = "white") + geom_text(aes(label = txt), size = 2, family = FONT) +
  scale_fill_gradient2(low = OI[["blue"]], mid = "white", high = OI[["verm"]], limits = c(-1, 1), name = "r") +
  labs(x = NULL, y = NULL) + theme_ms() + theme(axis.line = element_blank(), axis.ticks = element_blank())
src("FigS6", fs6)
save_ms("FigS6", list(list(plots = list(ps6), widths = 1)), heights = 1, w_mm = W_HALF, h_mm = 72)

say("")
say("All done: 6 main figures and 6 supplementary figures, each as PDF and TIFF; source data: ",
    length(base::list.files(OUT_DIR, pattern = "^source_data_")), " CSV files, in ", OUT_DIR)
log_stop()
